import { createInterface } from 'node:readline';
const clip = (s, n) => { s = String(s ?? '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '…' : s; };
const rl = createInterface({ input: process.stdin });
const TXT = Number(process.argv[2] || 400);
let prev = null, first = null, last = null;
const gaps = [];
const toolCounts = new Map();
let nUser = 0, nAsst = 0, nErr = 0;
const out = [];
for await (const line of rl) {
  let e; try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp ? new Date(e.timestamp) : null;
  if (ts) { if (!first) first = ts; last = ts; if (prev) { const d = (ts - prev) / 1000; if (d >= 25) gaps.push([prev.toISOString().slice(11,19), d.toFixed(0)]); } prev = ts; }
  const m = e.message;
  if (!m) continue;
  const t = ts ? ts.toISOString().slice(11, 19) : '--:--:--';
  const content = Array.isArray(m.content) ? m.content : (typeof m.content === 'string' ? [{ type: 'text', text: m.content }] : []);
  for (const c of content) {
    if (c.type === 'text' && c.text?.trim()) {
      if (m.role === 'user') { nUser++; out.push(`[${t}] USER: ${clip(c.text, 1200)}`); }
      else { nAsst++; out.push(`[${t}] ASST: ${clip(c.text, TXT)}`); }
    } else if (c.type === 'tool_use') {
      toolCounts.set(c.name, (toolCounts.get(c.name) || 0) + 1);
      const inp = clip(JSON.stringify(c.input), 220);
      out.push(`[${t}] TOOL ${c.name}: ${inp}`);
    } else if (c.type === 'tool_result') {
      const body = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
      if (c.is_error) { nErr++; out.push(`[${t}]   ERR: ${clip(body, 300)}`); }
      else if (/error|not found|failed|refus|denied|cannot|unable/i.test(String(body).slice(0, 400))) out.push(`[${t}]   res!: ${clip(body, 220)}`);
    }
  }
}
console.log(`## span ${first?.toISOString()} → ${last?.toISOString()}  (${first&&last?((last-first)/60000).toFixed(1):'?'} min)  userMsgs=${nUser} asstMsgs=${nAsst} toolErrs=${nErr}`);
console.log('## tools: ' + [...toolCounts].sort((a,b)=>b[1]-a[1]).map(([k,v])=>`${k}×${v}`).join(', '));
console.log('## gaps>=25s: ' + gaps.map(g=>`${g[0]}+${g[1]}s`).join(' ') + ` (total idle ${gaps.reduce((a,g)=>a+ +g[1],0)}s)`);
console.log(out.join('\n'));

